alter table public.timeline_daw_normalization_proofs add column if not exists active_history_id text,add column if not exists approved_at timestamptz;
alter table public.timeline_daw_normalization_proof_history add column if not exists transform_plan jsonb not null default '[]'::jsonb,add column if not exists revision_checksum text,add column if not exists promoted_lane_ids jsonb not null default '[]'::jsonb,add column if not exists restored_from_revision integer;
alter table public.timeline_daw_private_audio_lanes add column if not exists normalization_revision integer,add column if not exists superseded_at timestamptz,add column if not exists superseded_by_lane_id text;
create table if not exists public.timeline_daw_normalization_master_proofs(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,proof_id text not null references public.timeline_daw_normalization_proofs(id) on delete cascade,revision integer not null,source_id text not null,source_uri text not null,source_checksum text not null check(source_checksum~'^sha256:[a-f0-9]{64}$'),created_at timestamptz not null default now(),unique(owner_id,session_id,revision));
alter table public.timeline_daw_normalization_master_proofs enable row level security;
create policy timeline_daw_normalization_master_proofs_owner on public.timeline_daw_normalization_master_proofs for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create index if not exists timeline_daw_normalization_lanes_active on public.timeline_daw_private_audio_lanes(owner_id,session_id,normalization_revision) where superseded_at is null;